#!/bin/sh
# Starts Xvfb, the probe window, and freerdp-shadow-cli with NTLM NLA from a SAM file.
# HARNESS_USER / HARNESS_PASS are one-time credentials generated by run-engine-harness.sh.
set -eu
: "${HARNESS_USER:?}" "${HARNESS_PASS:?}"
SCREEN_WIDTH="${SCREEN_WIDTH:-1280}"
SCREEN_HEIGHT="${SCREEN_HEIGHT:-800}"
export DISPLAY=:0 SCREEN_WIDTH SCREEN_HEIGHT

Xvfb :0 -screen 0 "${SCREEN_WIDTH}x${SCREEN_HEIGHT}x24" -nolisten tcp &
for _ in $(seq 1 50); do [ -e /tmp/.X11-unix/X0 ] && break; sleep 0.1; done
python3 /harness/probe.py &

mkdir -p /run/harness
winpr-hash -u "${HARNESS_USER}" -p "${HARNESS_PASS}" -f sam > /run/harness/sam
unset HARNESS_PASS

exec freerdp-shadow-cli /port:3389 /sec:nla /sam-file:/run/harness/sam ${SHADOW_EXTRA_ARGS:-}
